function rollAwakenRank(score = 0, rng = Math.random) {
  const s = Math.max(0, score);
  const w = [Math.max(22, 62 - s * 6), 25 + s * 2, 9 + s * 2, 3 + s, 1 + s * 0.4];
  let r = rng() * w.reduce((a, b) => a + b, 0);
  for (let i = 0; i < w.length; i++) {
    r -= w[i];
    if (r < 0) return i;
  }
  return 0;
}
const PRO_FRIEND_JOBS = ["편의점 점장 대행", "간호학과 학생", "게임 회사 QA", "동네 태권도 사범", "배달 라이더", "공무원 준비생", "카페 바리스타", "자동차 정비공"];
function proText(t, flags) {
  return String(t).replace(/\{\?(!?)(\w+):([^|{}]*)\|([^{}]*)\}/g, (m, neg, f, a, b) => !!flags[f] !== !!neg ? a : b);
}
function proSceneText(sc, flags) {
  if (sc.textBy) {
    for (const [k, v] of Object.entries(sc.textBy)) if (flags[k]) return v;
  }
  return sc.text;
}
function proRemember(sc, flags, id, ch) {
  for (const f of [].concat(ch.flag || [])) flags[f] = true;
  const nx = ch.next;
  if (nx) {
    if (/^(gb_|gate_break)/.test(nx)) {
      flags[nx] = true;
      flags.arc_gb = true;
    } else if (/_1$/.test(nx) && !/^(chaebol|orphan|soldier|subject|student)_/.test(nx)) flags["arc_" + nx.replace(/_1$/, "")] = true;
  }
  if (nx && /^verdict/.test(nx) && ch.c) {
    let best = null, bv = 0;
    for (const [k, v] of Object.entries(ch.c)) if (v > bv) {
      bv = v;
      best = k;
    }
    if (best) sc.fate = best;
  }
}
function resolvePrologue(sc, rng = Math.random) {
  const top = (o, keys) => {
    let best2 = keys[0], bv = -1;
    for (const k of keys) {
      const v = (o[k] || 0) + rng() * 0.5;
      if (v > bv) {
        bv = v;
        best2 = k;
      }
    }
    return best2;
  };
  const element = top(sc.e, ELEMENT_KEYS);
  const talent = Math.max(1, Math.min(10, 4 + (sc.talent || 0) + Math.floor(rng() * 3) - 1));
  const luck = (sc.luck || 0) + talent * 0.4;
  const groups = Object.keys(CLASS_GROUPS).filter((g) => g !== "hidden");
  const grp = top(sc.g, groups);
  const pool = CLASSES.filter((c) => c.g === grp && c.r < 3);
  const rare = [10, 4 + luck * 0.6, 1 + luck * 0.4];
  const weights = pool.map((c) => rare[c.r] * (1 + (sc.c[c.id] || 0) * 1.5));
  let r = rng() * weights.reduce((a, b) => a + b, 0), best = pool[0];
  for (let i = 0; i < pool.length; i++) {
    r -= weights[i];
    if (r < 0) {
      best = pool[i];
      break;
    }
  }
  const fate = sc.fate && CLASSES.find((c) => c.id === sc.fate && c.r < 3);
  if (fate && rng() < [0.95, 0.88, 0.75][fate.r] + Math.min(0.1, luck * 0.02)) best = fate;
  const clash = { genius: "slow_learner", slow_learner: "genius", lucky: "cursed", cursed: "lucky", charisma: "loner", loner: "charisma" };
  const traits = [];
  const ranked = Object.entries(sc.t).sort((a, b) => b[1] - a[1] + (rng() - 0.5) * 0.3).map(([k]) => k);
  for (const id of ranked) {
    if (traits.length >= 3) break;
    if (clash[id] && traits.includes(clash[id])) continue;
    if (traitById(id)) traits.push(id);
  }
  while (traits.length < 3) {
    const t = TRAITS[Math.floor(rng() * TRAITS.length)].id;
    if (!traits.includes(t) && !(clash[t] && traits.includes(clash[t]))) traits.push(t);
  }
  const rank = rollAwakenRank((sc.talent || 0) + (sc.luck || 0) * 0.7 + (talent >= 7 ? 1 : 0), rng);
  return { element, talent, cls: best.id, traits, rank };
}
