      maxHp: Math.round(100 * m * cm("hp")),
      mp: Math.round(50 * m * cm("mp")),
      maxMp: Math.round(50 * m * cm("mp")),
      atk: Math.round(20 * m * cm("atk")),
      def: Math.round(8 * m * cm("def")),
