      c.fillRect(px - w / 2, py - 10, w, 20);
      c.fillStyle = known ? reg.guild ? GUILDS[reg.guild].color : "#46e0d0" : "#3a4658";
      c.fillRect(px - w / 2, py + 8, w, 2);
