    c.beginPath();
    c.arc(px, py, R + 4 + pulse * 6, 0, Math.PI * 2);
    c.stroke();
    c.fillStyle = "rgba(0,0,0,.5)";
    c.beginPath();
    c.ellipse(px, py + R * 0.95, R * 0.9, R * 0.25, 0, 0, Math.PI * 2);
    c.fill();
    c.save();
    c.beginPath();
    c.arc(px, py, R, 0, Math.PI * 2);
    c.clip();
