const NEG_TRAITS = ["slow_learner", "cursed", "frail"];
Object.assign(Game.prototype, {
  debutTier() {
    const p = this.player;
    const r = p.rankIdx;
    const t = p.talent;
    const neg = (p.traits || []).filter((x) => NEG_TRAITS.includes(x)).length;
    if (r >= 3 || r === 2 && t >= 7) return "star";
    if (r === 2 || r === 1 && t >= 6) return "rising";
    if (r === 0 && (t <= 4 || neg >= 1)) return "bottom";
    return "normal";
  },
  debutStart() {
    const p = this.player;
    if (p.debut) return;
    const tier = this.debutTier();
    p.debut = { tier, step: 0, at: this.monthKey(), npc: null };
    this.lifeEvent("".concat(DEBUT_TIERS[tier].name, "(으)로 헌터 생활을 시작했다."));
  },
  debutNext() {
    const d = this.player.debut;
    if (!d) return;
    d.step++;
    d.at = this.monthKey();
    if (d.step >= 5) d.done = true;
  },
  // 조건이 맞으면 다음 단계를 띄운다. 게이트 직후나 맞지 않는 장소에서는 기다린다
  debutDue(force) {
    const d = this.player.debut;
    if (!d || d.done || d.queued) return null;
    const ev = this.storyById("debut_".concat(d.tier, "_").concat(d.step));
    if (!ev) return null;
    if (!force && this.monthKey() - d.at < DEBUT_TIERS[d.tier].gaps[d.step]) return null;
    if (this.afterGate) return null;
    if (ev.at && !ev.at.includes(this.situation ? this.situation() : this.onCity() ? "city" : "field")) return null;
    d.queued = true;
    return { type: "story", id: ev.id, npc: d.step === 2 ? d.npc : null };
  },
  // 데뷔 시나리오에 등장하는 인물을 만든다
  debutNpc(o) {
    const p = this.player;
    const n = this.makeNpc(false, o.race || "human");
    n.rankIdx = Math.max(0, Math.min(7, o.rank));
    n.stage = RNG.int(0, 2);
    n.region = p.region;
    n.met = true;
    n.relation = o.rel || 0;
    n.personality = o.pers || n.personality;
    if (o.cls) n.cls = o.cls;
    n.ageMonths = (o.age || 24 + n.rankIdx * 3) * 12;
    n.lifespan = Math.max(n.lifespan, Math.floor(n.ageMonths / 12) + 20);
    n.links = {};
    n.disciples = [];
    n.parents = [];
    n.guild = o.guild || null;
    this.npcs.push(n);
    p.debut.npc = n.id;
    return n;
  },
  debutJoinGuild(id, bonus) {
    const p = this.player;
    if (p.crew) this.crewLeave && this.crewLeave("quit");
    p.guild = id;
    p.guildRank = 0;
    p.contrib = 0;
    this.lifeEvent("".concat(GUILDS[id].name, "에 입단했다."));
    return this.gain({ money: bonus });
  }
});
